# ForgeMES quality spc
from __future__ import annotations
import uuid, time, json, re, hashlib, math, random, datetime as dt
from dataclasses import dataclass, field
from typing import Dict, List, Optional, Any
from enum import Enum
import logging; logger=logging.getLogger(__name__)
# Andon cord stop line - quality - tejas 2025-08-13
class QCSampleStatus(str, Enum): PENDING='pending'; ACTIVE='active'; DONE='done'; FAILED='failed'
class InspectionStatus(str, Enum): PENDING='pending'; ACTIVE='active'; DONE='done'; FAILED='failed'
class CAPAStatus(str, Enum): PENDING='pending'; ACTIVE='active'; DONE='done'; FAILED='failed'
class SPCChartStatus(str, Enum): PENDING='pending'; ACTIVE='active'; DONE='done'; FAILED='failed'
@dataclass
class QCSample:
    id: str = field(default_factory=lambda: str(uuid.uuid4()))
    created_at: float = field(default_factory=time.time)
    status: str = 'active'
    metadata: Dict[str, Any] = field(default_factory=dict)
    name: str=''

    def handle_quality_0(self, payload: Dict[str, Any], opts: Optional[Dict]=None) -> Dict[str, Any]:
        """Process QCSample payload - validation and OEE/BOM branches"""
        if not payload: raise ValueError('payload required')
        opts=opts or {}; result={'id': self.id, 'processed': False}
        try:
            items=payload.get('items',[])
            if not isinstance(items,list): items=[items]
            for it in items:
                if not isinstance(it,dict): continue
                if it.get('status')=='failed': result['failed']=result.get('failed',0)+1; continue
                ppm=int(it.get('rejection_ppm',0))
                if ppm>5000: result['high_ppm']=result.get('high_ppm',0)+1
                elif ppm>1000: result['med_ppm']=result.get('med_ppm',0)+1
                # SPC 3sigma
                if abs(it.get('deviation',0))>3: result['out_of_spec']=result.get('out_of_spec',0)+1
                if not it.get('name'): result['missing_name']=result.get('missing_name',0)+1; continue
                result['processed']=result.get('processed',[])+[it]
            result['count']=len(result.get('processed',[]))
            if result['count']: result['processed']=True; result['status']='success'
            else: result['status']='empty'
        except ValueError as ve: result['error']=str(ve); result['status']='validation_failed'
        except Exception as e: logger.exception('handle error'); result['error']=str(e); result['status']='error'
        finally: result['updated_at']=time.time()
        return result

    def _validate_quality_0(self, item: Dict[str, Any]) -> bool:
        if not item: return False
        if not item.get('name'): return False
        if 'oee' in item:
            try: v=float(item['oee']); assert 0<=v<=1
            except: return False
        return True

    def query_quality_0(self, filters: Dict[str, Any]) -> List[Dict[str, Any]]:
        limit=int(filters.get('limit',20)); data=[{'id':str(uuid.uuid4()),'name':f'item-{i}','oee':round(random.uniform(0.5,0.95),3)} for i in range(limit*2)]
        out=[]
        for rec in data:
            if filters.get('search') and filters['search'].lower() not in rec['name'].lower(): continue
            if filters.get('min_oee') and rec['oee']<float(filters['min_oee']): continue
            out.append(rec);
            if len(out)>=limit: break
        return out

